use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::{BTreeMap,BTreeSet},fs,path::Path,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-vector-sign175";
const Z:&str="/home/ubuntu/src/zk-tools/zopro";
const D:&str="docs/benchmarks/2026-10-30-g2-vector-sign175";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn close(a:f64,b:f64){assert!((a-b).abs()<=1e-12*a.abs().max(b.abs()).max(1.));}
fn med(mut x:Vec<f64>)->f64{x.sort_by(f64::total_cmp);assert!(x.len()%2==1);x[x.len()/2]}
fn stats(x:&[f64],v:&Value){let mut y=x.to_vec();y.sort_by(f64::total_cmp);assert_eq!(y.len(),31);for(i,k)in[(9,"low"),(15,"median"),(21,"high")]{close(y[i],v[k].as_f64().unwrap());}assert_eq!(x.iter().filter(|&&n|n<1.).count()as u64,v["wins"].as_u64().unwrap());for(a,b)in x.iter().zip(v["ratios"].as_array().unwrap()){close(*a,b.as_f64().unwrap());}}
fn main(){
 let root=Path::new(R);let doc=Path::new(Z).join(D);let pins=read(root.join("pins.json"));
 for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(&fs::read(p).unwrap()),h.as_str().unwrap());}
 let manifest=read(Path::new(Z).join("docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json"));
 let originals=manifest["source_files_sha256"].as_object().unwrap();assert_eq!(originals.len(),175);
 let audit=read(root.join("source-audit.json"));let mut exact=0;
 for(p,h)in originals{let accepted=fs::read(Path::new(Z).join(p)).unwrap();assert_eq!(hash(&accepted),h.as_str().unwrap());let bytes=fs::read(root.join("source").join(p)).unwrap();if bytes==accepted{exact+=1;}else{let e=&audit["edits"][p];let mut t=String::from_utf8(bytes).unwrap();if let Some(s)=e["suffix"].as_str(){t=t.strip_suffix(s).unwrap().to_string();}if let Some(s)=e["after"].as_str(){assert_eq!(t.matches(s).count(),1);t=t.replacen(s,e["before"].as_str().unwrap(),1);}assert_eq!(t.as_bytes(),accepted);} }
 assert_eq!(exact,171);
 let mut commands=0;for dir in["native","links","runs"]{let result=read(root.join(dir).join("result.json"));assert_eq!(result["status"],"complete");for step in result["steps"].as_array().unwrap(){let p=root.join(dir).join(step.as_str().unwrap());let e=read(p.join("exit.json"));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for stream in["stdout","stderr"]{assert_eq!(hash(&fs::read(p.join(format!("{stream}.log"))).unwrap()),e[format!("{stream}_sha256")].as_str().unwrap());}commands+=1;}}assert_eq!(commands,440);
 let jobs=read(root.join("jobs.json"));assert_eq!(jobs.as_array().unwrap().len(),396);let mut total=0;let mut cells=BTreeMap::<String,BTreeMap<u64,f64>>::new();
 for j in jobs.as_array().unwrap(){let log=fs::read_to_string(root.join("runs").join(j["name"].as_str().unwrap()).join("stdout.log")).unwrap();let matches=log.lines().filter_map(|l|l.strip_prefix("RESULT ")).collect::<Vec<_>>();assert_eq!(matches.len(),1);let out:Value=serde_json::from_str(matches[0]).unwrap();let calls=j["calls"].as_u64().unwrap();assert_eq!(out["calls"],calls);assert_eq!(out["primes"],3);total+=calls+3;for k in["input_points_unchanged","all_outputs_match_independent_Arkworks","reset_copy_inside_clock","query_includes_grouping_and_all_MSM_stages","solver_outside_clock"]{assert_eq!(out[k],true);}assert_eq!(out["SDK_requests"],0);assert_eq!(out["result_sha256"],read(j["case"]["oracle"].as_str().unwrap())["expected_canonical_result_sha256"]);
 let ns=out["query_ns"].as_array().unwrap();assert_eq!(ns.len()as u64,calls);let m=med(ns.iter().map(|n|n.as_u64().unwrap()as f64).collect())/1e6;close(m,out["median_ms"].as_f64().unwrap());if j["panel"]=="latency"{let key=format!("{}/{}",j["case"]["name"].as_str().unwrap(),j["variant"].as_str().unwrap());assert!(cells.entry(key).or_default().insert(j["block"].as_u64().unwrap(),m).is_none());}}
 assert_eq!(total,9216);let a=read(root.join("analysis.json"));let mut failures=BTreeSet::new();let mut allratios=BTreeMap::new();let mut distributions=0;
 for case in["1x2-w1","1x2-w16","1x2-w32","2x2-w32"]{for arm in["FROZEN","OFF","ON"]{let c=&cells[&format!("{case}/{arm}")];assert_eq!(c.len(),31);close(med(c.values().copied().collect()),a["cells"][format!("{case}/{arm}")]["median_ms"].as_f64().unwrap());}
 for control in["OFF","FROZEN"]{let key=format!("{case}/ON/{control}");let x=(0..31).map(|b|cells[&format!("{case}/ON")][&b]/cells[&format!("{case}/{control}")][&b]).collect::<Vec<_>>();let v=&a["pairs"][&key];stats(&x,&v["statistics"]);let mut y=x.clone();y.sort_by(f64::total_cmp);let pass=if case=="1x2-w32"{y[21]<1.&&x.iter().filter(|&&r|r<1.).count()>=21}else{y[21]<=1.02};assert_eq!(v["passed"],pass);if !pass{failures.insert(key.clone());}allratios.insert(key,x);distributions+=1;}
 let x=(0..31).map(|b|cells[&format!("{case}/OFF")][&b]/cells[&format!("{case}/FROZEN")][&b]).collect::<Vec<_>>();let v=&a["calibration"][case];stats(&x,&v["statistics"]);let mut y=x;y.sort_by(f64::total_cmp);let pass=y[9]>=1./1.03&&y[21]<=1.03;assert_eq!(v["passed"],pass);if !pass{failures.insert(format!("{case}/OFF/FROZEN/calibration"));}distributions+=1;}
 for control in["OFF","FROZEN"]{let x=(0..31).map(|b|((allratios[&format!("1x2-w32/ON/{control}")][b].ln()+allratios[&format!("2x2-w32/ON/{control}")][b].ln())/2.).exp()).collect::<Vec<_>>();let v=&a["two_shape_aggregate"][control];stats(&x,&v["statistics"]);let mut y=x.clone();y.sort_by(f64::total_cmp);let pass=y[21]<1.&&x.iter().filter(|&&r|r<1.).count()>=21;assert_eq!(v["passed"],pass);if !pass{failures.insert(format!("two_shapes/ON/{control}/gain"));}distributions+=1;}
 assert_eq!(failures,a["failed_checks"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect());assert_eq!(a["caller_gate"],failures.is_empty());assert_eq!(a["eligible_for_SDK_stage"],failures.is_empty()&&a["diagnostic_qualified"]==true);
 let arcs=read(doc.join("artifacts/archive-review.json"));let mut members=0;for kind in["source","helpers","receipts","observations"]{let p=doc.join(format!("artifacts/{kind}.json.gz"));assert_eq!(hash(&fs::read(&p).unwrap()),arcs[kind]["sha256"].as_str().unwrap());let out=Command::new("gzip").arg("-dc").arg(&p).output().unwrap();assert!(out.status.success());let data:Value=serde_json::from_slice(&out.stdout).unwrap();assert_eq!(data.as_object().unwrap().len()as u64,arcs[kind]["members"].as_u64().unwrap());for (_,e)in data.as_object().unwrap(){let bytes=if let Some(s)=e["utf8"].as_str(){s.as_bytes().to_vec()}else{let h=e["hex"].as_str().unwrap();(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect()};assert_eq!(hash(&bytes),e["sha256"].as_str().unwrap());assert_eq!(bytes.len()as u64,e["bytes"].as_u64().unwrap());members+=1;}}
 assert_eq!(hash(&fs::read("/home/ubuntu/src/zopro-perf-work/balanced-kh-production/native/candidate-sdk").unwrap()),"20fde19fcfc2f06bb5c640a0ed0fd313fa73af8d03ed46e5df7fdc377791e99f");let inherited=read(root.join("inherited-summary/data.json"));assert_eq!(inherited["rows"].as_array().unwrap().len(),9);assert_eq!(read(doc.join("accepted-rows.json")),inherited["rows"]);assert_eq!(inherited["historical_distinct_Gnark_ledger"],25231);
 let review=json!({"postcapture_independent_check":true,"capture_pins_verified":pins.as_object().unwrap().len(),"production_files_verified":175,"private_exact_originals":exact,"source_reverses_all175":true,"successful_commands_verified":commands,"complete_queries":total,"paired_distributions_recomputed_from_integer_query_ns":distributions,"gate_decisions_verified":14,"failed_checks_verified":failures.len(),"archived_members_verified":members,"accepted_sdk_sha256_verified":true,"accepted_rows_verified":9,"capture_or_test_reruns":0,"caller_gate":a["caller_gate"],"production_changed":false,"goal_achieved":false});
 fs::write(root.join("postcapture-review.json"),serde_json::to_vec_pretty(&review).unwrap()).unwrap();println!("{review}");
}
